/* Define to prevent recursive inclusion -------------------------------------*/
#ifndef AI_DPU_H
#define AI_DPU_H

/* Includes ------------------------------------------------------------------*/
#include <stdint.h>
#include "main.h"
/* APP_LOW_LAT must be visible before dpu_config.h resolves
 * AUDIO_ACQ_LEN, or this translation unit silently disagrees with any TU that
 * does see it -- mirrors H7's Dpu/Inc/dpu.h. */
#include "app_config.h"
#include "dpu_config.h"
#include "ll_aton_runtime.h"
#include "ai_platform.h"
#include "stai_network.h"
#include "aiTestUtility.h"
#include "network.h"

/* The build configuration selects a network.h via its include
 * path, not via #ifdef; this is the compile-time proof that the one actually
 * reachable here is the one AI_MODEL_FULL claims it is. The cast to
 * uintptr_t avoids -Waddress (the compiler otherwise treats the constant-
 * folded strstr() result as a "can never be NULL" pointer comparison). */
#ifdef AI_MODEL_FULL
_Static_assert((uintptr_t)__builtin_strstr(LL_ATON_NETWORK_ORIGIN_MODEL_NAME, "full") != 0,
               "AI_MODEL_FULL is defined but the reachable network.h is not the full variant -- check this configuration's include path");
#else
_Static_assert((uintptr_t)__builtin_strstr(LL_ATON_NETWORK_ORIGIN_MODEL_NAME, "partial") != 0,
               "AI_MODEL_FULL is not defined but the reachable network.h is not the partial variant -- check this configuration's include path");
#endif /* AI_MODEL_FULL */

/* Exported constants --------------------------------------------------------*/
#define AI_DPU_X_CUBE_AI_API_MAJOR (1)
#define AI_DPU_X_CUBE_AI_API_MINOR (0)
#define AI_DPU_X_CUBE_AI_API_MICRO (0)
#define AI_DPU_INPUT               (5U)
#define AI_DPU_OUTPUT              (5U)

/* Exported types ------------------------------------------------------------*/
typedef struct
{
  stai_network *p_network;
  stai_ptr *p_stai_inputs;
  stai_ptr *p_stai_outputs;
  stai_network_info info;
  float input_Q_inv_scale;
  int16_t input_Q_offset;
  float out;
} AIProcCtx_t;

/* Exported functions --------------------------------------------------------*/
/**
 * @brief Initializes the STAI runtime and network instance.
 * @param pxCtx Pointer to the AI processing context to initialize.
 * @retval DPU_OK when the runtime, network, and I/O buffers are initialized.
 * @retval DPU_ERROR when an STAI initialization or I/O query fails.
 */
DPU_StatusTypeDef AiDPULoadModel(AIProcCtx_t *pxCtx);

/**
 * @brief Deinitializes the STAI network instance and runtime.
 * @param pxCtx Pointer to the initialized AI processing context.
 * @retval DPU_OK when the network and runtime are deinitialized.
 * @retval DPU_ERROR when either deinitialization operation fails.
 */
DPU_StatusTypeDef AiDPUReleaseModel(AIProcCtx_t *pxCtx);

/**
 * @brief Runs synchronous inference and stores the scaled primary output.
 * @param pxCtx Pointer to the initialized AI processing context.
 * @retval DPU_OK when inference completes successfully.
 * @retval DPU_ERROR when the STAI network execution fails.
 */
DPU_StatusTypeDef AiDPUProcess(AIProcCtx_t *pxCtx);

#endif /* AI_DPU_H */
